INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dancing Blade Katteni Momotenshi!', 'Dancing Blade is an anime FMV game. The player simply watches each scene as it proceeds; the only interaction is occasionally selecting dialogue choices when prompted. Depending on the player''s choices, they will reach one of four different endings. Once an ending is reached, the scenario leading to that ending can later be replayed without interruption. Any scene already viewed can also be freely revisited.' FROM games WHERE igdb_id = 64856 ON CONFLICT (game_id, language_code) DO NOTHING;
