INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('microsoft-pinball-arcade', 16968, '1998-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6psk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kgwflmncnpndpegnxpg4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Pinball Arcade', 'The programmers at Microsoft are porting a game from their operating system over to the Game Boy Color with MICROSOFT PINBALL ARCADE. This pinball game was great fun on the PC, and now it is in a form that can be taken anywhere. There are seven different tables that are actually representative of real boards made by pinball giant Gottlieb throughout the last century. Each board carries a different theme, whether it is space travel or a haunted house. The boards also contain a varying number of paddles and paddle locations to make each a different playing experience. The graphics in this version are not as shiny as its computer counterpart, but they do translate well to the small color screen. The sound effects and music remain largely the same, adding to the game''s arcade feel. The cartridge also contains a short but detailed history of pinball and how it has evolved over the years. MICROSOFT PINBALL ARCADE gives players the classic game with enough boards and extras to keep even the experts busy for quite a while.' FROM games WHERE igdb_id = 16968 ON CONFLICT (game_id, language_code) DO NOTHING;
