INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grover''s Travels', 'Grover''s Travels is a 1998 CD-ROM game developed by Encore Software and Children''s Television Workshop. In this parody of Gulliver''s Travels, users join Grover as he meets Big Bird, Elmo, Mr. Snuffleupagus and more. There are six activities designed to teach numbers, shapes, sound recognition, story comprehension and emotions.' FROM games WHERE igdb_id = 333206 ON CONFLICT (game_id, language_code) DO NOTHING;
