INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bard''s Lore: The Warrior and the Dragon', 'Welcome to the mystic world of THE BARD''S LORE. Deriving from the Bard''s Tale series, it takes you into the limit of adventuring. If you can beat Grendel, you will truly prove yourself to be a worthy adventurer! But there are some major monsters out there, just waiting to take a bite out of you...you must use all your cunning and wits to solve this one.' FROM games WHERE igdb_id = 335045 ON CONFLICT (game_id, language_code) DO NOTHING;
