INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dezaemon 3D', 'Dezaemon 3D is a video game and game creator for the Nintendo 64. It was released only in Japan in 1998. The game''s editor allows players to design their own shooting game levels similar to the levels shown in Star Soldier: Vanishing Earth. The game has a large number of options, from creating the stage boss or adding a custom soundtrack for each level. It was originally developed alongside an ultimately unreleased accompanying expansion disk title for 64DD.' FROM games WHERE igdb_id = 3470 ON CONFLICT (game_id, language_code) DO NOTHING;
