INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gilbert and the chemystical island', 'When the egg hatches and the dragon Gilbert takes his first steps onto the beach, there begins a chemical adventure the likes of which you have never before seen, It is an adventure where your own curiosity and thirst for knowledge steer the course of the game. In the hunt for the various parts of the egg shell, which are scattered to the winds, you will learn the secrets of chemistry accompanied by the lab assistant, the desert bedouin, the lava man, the snow queen, and several others.' FROM games WHERE igdb_id = 319364 ON CONFLICT (game_id, language_code) DO NOTHING;
