INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cross-tantei-monogatari-motsureta-nanatsu-no-labyrinth', 122982, '1998-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6t1b.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross Tantei Monogatari: Motsureta Nanatsu no Labyrinth', 'Cross Tantei Monogatari: Motsureta Nanatsu no Labyrinth is a Japanese adventure game about a young man named Ken Koruso that hopes to become a detective and solve the mystery behind the car accident that killed his father. The title was the very first game created by WorkJam, a developer founded by Yutaka Kaminaga that famously took over the Tantei Jinguji Saburo franchise after the closing of Data East. Cross Tantei Monogatari was initially released for the Sega Saturn in Japan on June 6, 1998 and featured seven different episodes that had their own mysteries to solve. The following year a PlayStation port was released that contained several enhancements including the main character being fully voiced among other improvements. A discounted version was also published in 2000 that was separated into two titles with episodes 1-4 being in the first game and episodes 5-7 in second game.' FROM games WHERE igdb_id = 122982 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 122982 AND c.slug = 'workjam' ON CONFLICT DO NOTHING;
