INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eggs of Steel: Charlie''s Eggcellent Adventure', 'Charlie has really done it this time. While reaching for his beloved donuts, he accidentally spilled coffee on his work station at the MomSteel Steel Factory. Now the machinery has taken on a life of its own! Assume control of Charlie the Egg in your effort to find the reset switch located somewhere within the factory.' FROM games WHERE igdb_id = 68023 ON CONFLICT (game_id, language_code) DO NOTHING;
