INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshimoto Mahjong Club', 'Yoshimoto Mahjong Club is a comedy-themed mahjong game featuring 26 real-life comedians from talent agency Yoshimoto Kogyo, based on a TV show that ran on SUN-TV between 1997 and 1999. The featured stars are all represented both in live-action video clips and fully-3D in-game models, including voice clips of their signature quips. There is a standard free battle mode, as well as a tournament mode with 16 different titles to win. Winning tournaments will earn money, which is needed to enter and participate in the more advanced tournaments. The PlayStation Deluxe version adds a video gallery mode but is otherwise the same game.' FROM games WHERE igdb_id = 382990 ON CONFLICT (game_id, language_code) DO NOTHING;
