INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slayers Wonderful', 'Slayers Wonderful is a role-playing video game developed by TamTam and released by Banpresto for the PlayStation in 1998 exclusively in Japan. It features key voice actors from the Slayers anime versions and a story supervised by the Slayers author Hajime Kanzaka. The game was a big commercial success but received mixed critical reception.' FROM games WHERE igdb_id = 71894 ON CONFLICT (game_id, language_code) DO NOTHING;
