INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bottom-of-the-9th-99', 43856, '1998-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqt0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5j31.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bottom of the 9th ''99', 'BOTTOM OF THE 9TH ‘99 brings all of the action and excitement of professional baseball to the PlayStation. With an MLBPA license, over 700 major league players are included with updated stats, and motion capture technology recreates the nuances of every single player. Get a quick baseball fix by putting your team on the field of 30 stadiums in the Exhibition or Training modes; or discover the pressure being on the mound, up by one run with one out and a man on third, in the Scenario mode. For the most realistic experience, tackle the ups and downs of a season, the playoffs, or a championship series. With the innovative cursor system for batting and pitching, the challenges of hitting a 100 mph fastball are faithfully recreated. The action of BOTTOM OF THE 9TH ''99 brings professional baseball to you without having to pay for admission.' FROM games WHERE igdb_id = 43856 ON CONFLICT (game_id, language_code) DO NOTHING;
