INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sutte Hakkun BS Version 2', 'Sutte Hakkun BS Version 2 is a platform/puzzle game that was released in 1998 in Japan. As the game''s title implies, it is a sequel of sorts to the earlier Sutte Hakkun (Nov. 1997) and Sutte Hakkun Event Version (Oct. 1997). A later titles in the same series, Sutte Hakkun ''98 (Dec. 1998) followed a month after the broadcast of Sutte Hakkun Version 2.' FROM games WHERE igdb_id = 150192 ON CONFLICT (game_id, language_code) DO NOTHING;
