INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods 99 PGA Tour Golf', 'Tiger Woods 99 PGA Tour Golf is the fourth PlayStation golf title from Electronic Arts and first to promise you''ll play 18 holes within 30 minutes. Play as the champion or one of seven other PGA Tour pros on five different 3D courses: TPC at Southwind, TPC at Summerlin, TPC at Las Colinas, TPC at Sawgrass and TPC of Scottsdale.
