INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lucky-luke-on-the-daltons-trail', 44968, '1998-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kdufgkt81eyslwbzfxv9.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Luke: On the Dalton''s Trail', 'You, as Lucky Luke, have to stop the Dalton gang from making another crime. Walking around town you have to solve puzzles, shoot criminals and collect money. After finishing the level you have a chance to buy an extra life with the money collected. Shooting isn''t ordinary, often Lucky needs to ricochet shots to hit his target. The game view sometimes changes from 2D style to behind the shoulders. The levels differ from town exploring, to bottle-shooting in a bar, to freeing hostages on the roof of train, to Indian sneaking. But, all of them lead Lucky to $1,000,000 for the capture of the Daltons.' FROM games WHERE igdb_id = 44968 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 44968 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
