INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tetris-the-grand-master', 25022, '1998-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3hgr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgj1f.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris: The Grand Master', 'The first entry in the Tetris: The Grand Master sub-series, this game plays similarly to other Tetris games, but rather than merely expecting the player to survive indefinitely, it challenges the player to attain the highest level and score they can in the shortest amount of time. The Grand Master series introduced several play mechanics to Tetris gameplay which can be seen today in its sequels and many other Tetris implementations.' FROM games WHERE igdb_id = 25022 ON CONFLICT (game_id, language_code) DO NOTHING;
