INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightlong: Union City Conspiracy', 'Nightlong: Union City Conspiracy is a classic point-and-click adventure game made in 1998 by Italian development studio Team 17. The player assumes the role of private eye Joshua Reev, who gets caught up in a conspiracy set in a futuristic metropolis inspired by future noir films like Blade Runner. Great locations and solid voice acting make the primarily inventory-based puzzles a good bit of fun to play.' FROM games WHERE igdb_id = 27379 ON CONFLICT (game_id, language_code) DO NOTHING;
