INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-gamebreaker-99', 43711, '1998-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lhk5ikaglue5tqwlaqv4.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA GameBreaker 99', 'NCAA GAMEBREAKER ''99 continues this series'' tradition of realistic college football simulations. You''ll get features like the Customize Play option, which lets you design your own plays and really makes the possibilities almost endless. While many other football games neglect the running game, NCAA GAMEBREAKER ''99 embraces it with open arms. Don''t be surprised to find yourself on a 60-yard sprint to the endzone! As the running game is essential to any successful college program, the emphasis on it in GAMEBREAKER truly makes this the most realistic football sim you''re likely to find. Of course, you also get all the standard gameplay modes, fully polygonal and texture-mapped players, and all of the college stadiums and team logos. NCAA GAMEBREAKER ''99 can be enjoyed by up to eight players through the use of the Multi-tap.If you''re ready to make a run at greatness, then get your hands on NCAA GAMEBREAKER ''99.' FROM games WHERE igdb_id = 43711 ON CONFLICT (game_id, language_code) DO NOTHING;
