INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Chess 64', 'Transform your N64 into a powerful chess adversary. The most awesome chess engine adapts to any skill level. Learning is endless fun yet even superb players face the maximum challenge. Brilliant graphics brings this classic game alive. Become the next chess legend!' FROM games WHERE igdb_id = 3334 ON CONFLICT (game_id, language_code) DO NOTHING;
