INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsukoi Monogatari', 'Hatsukoi Monogatari is a life sim/love adventure game and a remake of the 1993 PC game of the same title. While the story and gameplay are largely identical to the original version, this remake adds a new character — the angel Liliana — along with new events and endings. The artwork has also been completely redone in a different style, with new character designs by a different artist than the original release.' FROM games WHERE igdb_id = 330209 ON CONFLICT (game_id, language_code) DO NOTHING;
