INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clue Murder at Boddy Mansion', 'Based on the board game of the same name. It was developed in 1998 for Hasbro Interactive by EAI. Infogrames (now Atari) took over publishing rights for the game in 2000 when Hasbro Interactive went out of business. The game, just like the board game, is meant for 3-6 players due to the six suspects. The game garnered generally positive reviews upon release.' FROM games WHERE igdb_id = 28097 ON CONFLICT (game_id, language_code) DO NOTHING;
