INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choro-Q Jet: Rainbow Wings', 'Choro-Q Jet: Rainbow Wings is an action game in which the player controls a jetplane. it is for the PS1 console and was sold only in Japan. It is different from the other Choro-Q series because the game is a completely an action based game. So it does not have races and (even if it''s a jetplane race) your customized jetplane. The unique feature of this game is that anime characters (with voice actors) appear in the game.' FROM games WHERE igdb_id = 43770 ON CONFLICT (game_id, language_code) DO NOTHING;
