INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrecking Crew ''98', 'Wrecking Crew ''98 is a Japan-only puzzle video game released for the Super Famicom. It is the sequel to the Nintendo Entertainment System game Wrecking Crew. The game takes on a more competitive approach, featuring puzzle-versus elements akin to games like Tetris and Puyo Puyo. Such additions include chain reactions, as well as attacks unleashed into the opponent''s play area upon successfully clearing lines.' FROM games WHERE igdb_id = 42400 ON CONFLICT (game_id, language_code) DO NOTHING;
