INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kumitate Battle: Kuttu Ketto', 'Maboroshi Tsukiyo is an adventure game released for the Dreamcast and Playstation consoles, in which the player takes the role of Takashi Tanaka (the player can choose another name) that one summer evenight he meet the ghost of a girl in the park, and the ghost girl start living with him in his appartment. The first night the girl appears to one of Takashi friends and the girl vanished after seeing the ghost, the ghost can enter other people''s bodies too...' FROM games WHERE igdb_id = 70995 ON CONFLICT (game_id, language_code) DO NOTHING;
