INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stratego', 'Stratego, the popular board game of battlefield strategy, comes to life on the computer. You have an army of men and weapons at your disposal. Your mission: capture your opponent''s flag and protect your own. Your troops range in rank from scout to marshal--but your opponent doesn''t know the ranks of your players. Each is disguised as an innocent drummer boy marching across the battlefield while cautiously sidestepping hidden bombs. When engaged in battle, characters morph into toy soldiers, and their ranks determine who emerges victorious. This is the game for developing your strategic skills.' FROM games WHERE igdb_id = 88896 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 88896 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
