INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warcraft 2000: Nuclear Epidemic', 'In 1998 the GSC Game World studio tried to introduce itself to the Western video gaming market by making its first real-time strategy game. For that, the developers decided to make their own sequel to Warcraft II, using their own engine that would be used later for the Cossack games.' FROM games WHERE igdb_id = 233549 ON CONFLICT (game_id, language_code) DO NOTHING;
