INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Land Before Time: Math Adventure', 'The Land Before Time: Math Adventure is an educational game for Windows-based PCs intended for children ages 4-8. It was released by Sound Source Interactive in North America in 1998. It contains a series of math-oriented minigames that, like The Land Before Time Activity Center, reward the player with "tree stars" and "dino bucks" that can be used to unlock video clips (once again). The game was mentioned in the book Gadgets, Games and Gizmos for Learning by Karl M. Kapp as an example of electronic learning that can allow up-and-coming students to develop problem-solving skills.' FROM games WHERE igdb_id = 329646 ON CONFLICT (game_id, language_code) DO NOTHING;
