INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ReBoot', 'This 3D action game is based on the computer animated cartoon ReBoot. It''s an over-the-shoulder perspective shooter comprised of 19 complex levels filled with diverse enemies. The story in the game is conveyed through the linear video: an original episode of ReBoot created just for the game and positioned as episode 0 of the TV series (i.e. a prequel).' FROM games WHERE igdb_id = 51953 ON CONFLICT (game_id, language_code) DO NOTHING;
