INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely Girls', 'In this QIX variant, the screen should be filled as complete as possible with a picture of a naked female model. This is done by marking areas on the screen, which then (if there is no monster in them) are filled with the picture. When the player has filled 75% of the playfield the level is completed. The fill-area is marked with a white line, old filled white lines are marked as blue lines.' FROM games WHERE igdb_id = 134122 ON CONFLICT (game_id, language_code) DO NOTHING;
