INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Comer', 'You play the 28th “Comer”, the last person in a long line of famous individuals who have attempted to solve the mystery of creation and extinction of life. By chance he enters a forbidden zone reserved for an experiment and by following the trail of your predecessors, will intervene in the next cycle of creation and extinction.' FROM games WHERE igdb_id = 94225 ON CONFLICT (game_id, language_code) DO NOTHING;
