INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider and Web', 'Spider And Web is not a game about a vacation. It is a game about deception, incomplete knowledge, and the ways that stories in other people''s heads can be the best lies. It is also about the role of the narrator works in interactive fiction -- but you don''t have to worry about that to play the game. (Well, not much.)' FROM games WHERE igdb_id = 91916 ON CONFLICT (game_id, language_code) DO NOTHING;
