INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ojou-sama Express', 'The protagonist boards the special express train "Vega" that departs from Wakkanai in Hokkaido and travels through various cities such as Tokyo and Osaka over a period of 15 days, crossing Japan. During this journey, the objective of the game is to get to know and become friends with the girls who board the train at various stations, leaving behind enjoyable memories. The basic actions involve moving around the Vega''s train cars and tourist spots to find the girls and engage in multiple conversations to advance the scenario.' FROM games WHERE igdb_id = 270746 ON CONFLICT (game_id, language_code) DO NOTHING;
