INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie Nail Designer', 'Design personalized nail stickers you can really wear. Join Barbie at her fabulous nail salon and choose a style to match your own--Daisy Days, Cool Styles, or Glossy Glam. Choose from an array of colors and animated designs, from pinks and reds, blues and greens, to rainbows and fun jungle prints. You can even create your own special nail designs. Then add sparkles and other finishing touches for the ultimate digital manicure. Now print the nails you have designed on special sticker sheets included--and wear your nails for instant fingernail fun!' FROM games WHERE igdb_id = 200607 ON CONFLICT (game_id, language_code) DO NOTHING;
