INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CarnEvil', 'CarnEvil is a rail shooter arcade game using a light gun. It was released by Midway Games on October 31, 1998. CarnEvil is noted for its graphic content and strong lifelike violence, peppered with heavy amounts of black humor. CarnEvil is a portmanteau of "The Carnival of Evil" and was inspired by the 1962 movie Carnival of Souls. It is the most successful light gun style game produced by Midway Games, although to date it has never received a home-console release or re-release' FROM games WHERE igdb_id = 18632 ON CONFLICT (game_id, language_code) DO NOTHING;
