INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Blue Men', 'This game is a joke. This game is a warning. This game is a satire. This game is inspired in equal parts by Vaclav Havel''s "The Memorandum" and Hunter S. Thompson''s "Fear and Loathing in Las Vegas". This game is a big, stupid shaggy dog story.' FROM games WHERE igdb_id = 70787 ON CONFLICT (game_id, language_code) DO NOTHING;
