INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikuu Tantei DD 2: Hangyaku No Apsalar', 'Jikuu Tantei DD 2: Hangyaku No Apsalar is the sequel to Ascii''s Jikkuu Tantei. The game features the vampire detective again but instead of a sequel the game takes place in 2231 (7 years before the first game story).' FROM games WHERE igdb_id = 154835 ON CONFLICT (game_id, language_code) DO NOTHING;
