INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sotsugyou III: Wedding Bell', 'Sotsugyou III: Wedding Bell is the third game in the Sotsugyou graduation series. The game is a dating simulation first person adventure game. You''re a married teacher (to a former student) and you hand out assignments to students, go on dates with your wife, manage schedules, etc. At the beginning of the game the player can choose between one of the five characters he wants to be married to.' FROM games WHERE igdb_id = 166393 ON CONFLICT (game_id, language_code) DO NOTHING;
