INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncle Albert''s Magical Album', 'Uncle Albert''s Magical Album is the first game in a series based on the fictional character "Uncle Albert". Aimed at ages 7 and up (9 and up advertised in the US release), it consists of a series of puzzles that can be completed in a non-linear order. The player needs to reveal the secret of uncle Albert through a book in his attic. Solving the puzzles opens up new pages that lead to the secret.' FROM games WHERE igdb_id = 147321 ON CONFLICT (game_id, language_code) DO NOTHING;
