INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-custom-car-designer', 313290, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8o25.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctm15.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Custom Car Designer', 'Mattel Media''s Hot Wheels Custom Car Designer CD-ROM puts you or your child behind the virtual wrench, spray brush and stamp pad, allowing you to customize the appearance of 20 different traditional Hot Wheels models (including the jeep, speedboat, blimp and a number of racers). But why stop at detailing your dream machine when you can also draft licenses and traffic tickets, label trophies and ribbons, and create flags and license plates?
