INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic & Mayhem', 'Magic & Mayhem is a real-time strategy game. It combines elements of role-playing with strategy, action and puzzles. You play a young mage, Cornelius, who seeks to uncover the mystery surrounding the disappearance of his mentor. The result is adventures that will span three islands, which will uncover new mysteries and make new friends, and force you to face a multitude of challenges, puzzles and enemies.' FROM games WHERE igdb_id = 79804 ON CONFLICT (game_id, language_code) DO NOTHING;
