INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Incubation: Hidden Worlds', 'Incubation: Hidden Worlds is a special edition compilation that includes the full game Incubation: Time is Running Out along with additional content. The package features ten Instant Action maps offering tactical combat scenarios, with three maps exclusive to this edition. Players receive an audio CD containing the game''s soundtrack alongside music from Extreme Assault and Archimedean Dynasty. The compilation also includes a 4x4 concentration memory game, a playable demo of Incubation, and patches to update the game to version 1.03.' FROM games WHERE igdb_id = 70133 ON CONFLICT (game_id, language_code) DO NOTHING;
