INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bananas in Pyjamas: It''s Party Time', 'Bananas in Pyjamas, a worldwide phenomenon, and favorite for millions of children over the globe, has now come to the PC with this excellent new CD-ROM for young children. Join B1 and B2 on a wonderful adventure through the wacky world of Cuddles Avenue for hours of interactive fun and games. Bananas in Pyjamas help children develop a variety of skills, such as memory building, sequencing and problem solving. The program also enhances social skills such as sharing and co-operation, as well as encouraging children to join in with musical activities by playing instruments, singing and dancing.' FROM games WHERE igdb_id = 159092 ON CONFLICT (game_id, language_code) DO NOTHING;
