INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Pilot ''99', 'Pro Pilot is a flight program comparable to Flight Simulator. It focuses more on realistic flight operations, and less on gameplay. Flight startup is more complex, and instead of a visual map, there is a more technical GPS system. It includes six planes and scenery for the USA and Western Europe. Also included is an in-game "operations manual", flight instruction videos and training flight courses, all geared to prepare the user for the real thing. Hardware acceleration is supported only for 3Dfx cards.' FROM games WHERE igdb_id = 69960 ON CONFLICT (game_id, language_code) DO NOTHING;
