INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Bunnies Must Die!', 'Space Bunnies Must Die! is a third-person action-adventure game developed by Ripcord Games and released in 1998 by Jinx for Microsoft Windows 98. Player character is southern diner waitress Allison Huxley, who must save the world and her abducted sister from an invading race of mutant bunnies from space.' FROM games WHERE igdb_id = 51371 ON CONFLICT (game_id, language_code) DO NOTHING;
