INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airplane Tycoon', 'Airline Tycoon is a business simulation game by Thomas Holz and Robert Kleinert, in which the player must successfully manage an airline. The original was developed by Spellbound Entertainment, and published by Infogrames Deutschland, however, the succeeding versions were published by a variety of publishers.' FROM games WHERE igdb_id = 306638 ON CONFLICT (game_id, language_code) DO NOTHING;
