INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radikal Bikers', 'Radikal Bikers is set in a Mediterranean environment, and is based on delivering pizza on a rare Italian scooter called Italjet Dragster in heavy traffic before your AI opponent does, while getting points. It has three difficulty levels, which correspond to each of the different places: Capricciosa (medium, set in Rome), Margherita (easy, set in Milan) and Diabola (hard, set in Naples). If you beat all four races in a level, you get to play the next level free.' FROM games WHERE igdb_id = 44801 ON CONFLICT (game_id, language_code) DO NOTHING;
