INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganja Farmer', 'You are John Parker, Rastafarian soldier, trying to defend your herb/pot/weed/marijuana/ganja field against American soldiers. You stand on your Volkswagen bus 1969 and fire bullets to the landing soldiers. Also don''t forget to destroy bombers, helicopters and later on UFO, too. Game takes part in levels and after each level Rastafarian god Jah comes to help you, renew your weed plants and to give you some more power.' FROM games WHERE igdb_id = 25801 ON CONFLICT (game_id, language_code) DO NOTHING;
