INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CrossTown 1: Giften', 'CrossTown: Giften is the first game in the CrossTown series of mystery adventure games. Minna Walker explores the city of CrossTown, looking for clues and interrogating citizens in order to save the city itself from an impending catastrophe. The game features dialogue puzzles and tools to record and replay dialogue for clues.' FROM games WHERE igdb_id = 122315 ON CONFLICT (game_id, language_code) DO NOTHING;
