INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Symbiocom', 'The protagonist of this game is a maintenance engineer aboard I.S.T. Rident, a space-faring passenger liner in the delta quadrant. Suddenly, two war ships attack Rident. As the captain orders the passengers to escape on life boats, the hero is knocked unconscious. Some time later, he finds himself in a deserted spacecraft, and must find a way to escape from there, find out who was responsible for the attack on Rident, and what has happened to its passengers.' FROM games WHERE igdb_id = 8417 ON CONFLICT (game_id, language_code) DO NOTHING;
