INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon 2: Nobita to Hikari no Shinden', 'Doraemon 2: Nobita to Hikari no Shinden (Doraemon 2: Nobita and the Temple of Light) is an action game for the Nintendo 64. It was released only in Japan in 1998 . The game is based on the Japanese manga Doraemon and is the second in the Nintendo 64 series, it was preceded by Doraemon: Nobita to Mittsu no Seirei Ishi and followed by Doraemon 3: Nobi Dai no Machi SOS!, all only released in Japan.' FROM games WHERE igdb_id = 3473 ON CONFLICT (game_id, language_code) DO NOTHING;
