INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Rally Edition ''99', 'Racing insanity! Over 40 original tracks, 11 official World Rally Championship cars, tracks in 8 worldwide locations, realistic race physics and smooth car handling, diverse terrain such as jungles, canyons, deserts, mountains and more, unstable weather patterns like rain, fog, snow and cloudy. Adjust car performance characteristics to suit varied road conditions. Bonus and hidden cars and tracks to unlock!' FROM games WHERE igdb_id = 10621 ON CONFLICT (game_id, language_code) DO NOTHING;
