INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL Breakaway 99', 'All 27 NHL teams and over 600 players including the expansion Nashville Predators. Symbol-based passing and non-puck handler control. Real-life player sizes and weights. Create, trade, sign and release players. Set team style for physical play, power plays and penalty killing. Updated 1998-99 team jerseys, rosters, schedules and realigned divisions. Actual arena names for the ultimate NHL realism!' FROM games WHERE igdb_id = 3564 ON CONFLICT (game_id, language_code) DO NOTHING;
