INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speed-busters-american-highways', 46531, '1998-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tud.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rzomqzdvb8mfwxfvxb5d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Busters: American Highways', 'For centuries, the speed limit on American highways has been restricted by law. Technology now offers drivers the chance to make their own choice in the virtual world with Speed Busters: American Highways. The police have lost their minds and reward the fastest players to fly past their strategically placed radar! Earn cash to upgrade one of eight specially designed vehicles based on models ranging from the ‘50s to the ‘90s. Tackle mixed terrain, avoid shocking animations, and storm through environments based on real North American locations.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46531 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46531 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 46531 AND c.slug = 'ubisoft-montreal' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46531 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/rzomqzdvb8mfwxfvxb5d.jpg', 0, true FROM games WHERE igdb_id = 46531 ON CONFLICT DO NOTHING;
