INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/pg8hwkefnh5xedlk3ksh.jpg', 2, false FROM games WHERE igdb_id = 46531 ON CONFLICT DO NOTHING;
